package com.vk.starscriptmusic.domain.model

/**
 * Domain representation of a Playlist (User-created or Auto-Generated Artist Hub).
 */
data class Playlist(
    val id: Long,
    val name: String,
    val description: String? = null,
    val createdAt: Long = System.currentTimeMillis(),
    val isAutoGenerated: Boolean = false,
    val artistFilter: String? = null,
    val tracks: List<Track> = emptyList()
) {
    val totalDurationMs: Long
        get() = tracks.sumOf { it.durationMs }

    val trackCount: Int
        get() = tracks.size

    val coverArtUri: String?
        get() = tracks.firstOrNull { it.albumArtUri != null }?.albumArtUri
}
